from collections import deque

# Function to generate all possible numbers of the form x0, x1, ..., x'd-1 from a list nums
def generate_numbers(nums, d):
    from itertools import product
    numbers = []
    for x in nums:
        for y in range(x, x << d):
            num = bin(y).count('1')
            if num < x or not (y & (y - 1)):  # Check if binary representation is power of 2
                numbers.append(str(y))
    return deque(numbers)

# Function to find the position and the number that can be represented as a XOR sum of numbers in the basket
def find_number(basket, target):
    d = 1
    while target >= (1 << d):
        d += 1

    nums = deque(basket)
    for num in sorted(nums, reverse=True):
        d -= 1
        while num & (1 << d):
            _ = nums.popleft()
        if num < target:
            num, closest = num ^ target, target - num
            nums.appendleft(closest)
        elif not (num & (1 << (d + 1))):
            nums.appendleft(num ^ target)

        if num == target:
            return len(nums), nums.index(closest) + 1
    return 0, None

