def find_lookup_tables(K, Q, intervals):
    LookupTable = namedtuple('LookupTable', 'LSBTable firstMSBTable')
    for firstMSBTable in range(2 ** (K + 1)):
        valid_lookup = True
        for l, r, v in intervals:
            low_kbits = l >> (2 * K - K - 1)
            high_kbits = (r - l + 1) >> (2 * K - K - 1) - 1
            high_kbits = (r - high_kbits) + high_kbits
            result = (LSBTable[low_kbits] & MSBTable[high_kbits]) & MSBTable[high_kbits]
            if result != v:
                valid_lookup = False
                break
        if valid_lookup:
            LSBTable = set(firstMSBTable << x for x in range(K) | set(range(K + 1, K + 1 + Q)))
            return LookupTable(LSBTable, firstMSBTable)
    return None

