from typing import List

def get_edge_mask(n: int, m: int) -> List[int]:
    """
    Generate bitmask of bitwise AND for every edge in the complete graph.
    2^{n} * 2^{n} * (possible edges - 1)
    """
    AND_mask = [[0] * 2**(n+1) for _ in range(2**2*n+1)]
