import sys

def find(parent, i):
    if parent[i] == -1:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot == yroot:
        return False
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1
    return True

def count_components(num, mask_func):
    size = len(num)
    parent = [-1] * size
    rank = [0] * size
    connections = num[:]
    scc_count = 0
    for connection in connections:
        if union(parent, rank, connection & 0xffffffff, mask_func(connection // 32)):
            scc_count += 1
    return scc_count

def process(input_string):
    n, m = map(int, input_string.split())
    nums = [i for i in range(0, n) for _ in range(m)]
    ans = count_components(nums, sum)
    return ans

