from functools import reduce

def modular_inverse(a, m):
    """Calculate modular inverse using Extended Euclidean Algorithm."""
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make sure the result lies in the range [0, m-1]
    return x0 % m

def factorial_modulo(n, mod=1000000007):
    """Calculate n! mod mod using Fermat's Little Theorem."""
    if n == 0:
        return 1
    return reduce(lambda x, y: x * y % mod, (i for i in range(1, n + 1)))

# Calculate the expected value of the function F modulo 1,000,000,007.
def calculate_expected_value(n, mod=1000000007):
    if n == 2:
        return 2 % mod
    elif n == 3:
        return (5 % mod + 5 % mod + 8 % mod + 8 % mod + 9 % mod + 9 % mod) // 6 % mod

