class UnionFind:
    def __init__(self, n):
        self.size = n
        self.root = [*range(n)]

    def make_set(self, x):
        self.root[x] = x

    def find_set(self, x):
        while x != self.root[x]:
            self.root[x] = self.root[self.root[x]]
            x = self.root[x]
        return x

    def union_set(self, x, y):
        r1, r2 = self.find_set(x), self.find_set(y)
        if r1 == r2:
            return 1
        if self.size[r1] < self.size[r2]:
            self.root[r1] = r2
            self.size[r2] += self.size[r1]
        else:
            self.root[r2] = r1
            self.size[r1] += self.size[r2]
        return 0

def count_num_ways(N, K):
