from math import gcd
from functools import reduce
from collections import defaultdict

def solve(m, lst):
    def compute(index, nums):
        n = len(nums)
        x = 0
        while index >= 0:
            x += nums[index]
            index -= (index & -index)
        return x

    def compute_index(index, nums):
        while index >= n:
            index -= (index & -index)
        return index

    def compute_sum(nums):
        n = len(nums)
        suffix_sum = [0] * (n + 1)
        for i in range(n):
            suffix_sum[i + 1] = suffix_sum[i] ^ nums[i]
        return suffix_sum

    def find_or_update(nums, value):
        n = len(nums)
        index = 0
        for i in range(n):
            diff = value ^ nums[i]
            while index >= (1 << i):
                index -= (1 << i)
            if diff == 0:
                index += (1 << i)
            else:
                nums[i] ^= diff
        return nums, index

    def xor_by_remnant(nums):
        sums = compute_sum(nums)
        diffs = sum((sums[i + 1] ^ sums[i]) for i in range(len(nums)))
        zeros, ones = gcd(diffs), gcd(i for i in range(1, len(nums)) if sums[i] & (1 << (i - 1)))
        while zeros or ones:
            index = 1 << ((len(nums) - 1) & -len(nums))
            for i in range(len(nums)):
                nums_compute = compute_index(i, nums)
                if index & (0x1 << i):
                    nums[nums_compute] ^= ones
                else:
                    nums[nums_compute] ^= zeros
            zeros = gcd(i for i in range(1, len(nums)) if nums_compute == 0 if sums[i] & (1 << (i - 1)))
            ones = gcd(i for i in range(1, len(nums)) if nums_compute == 0 if sums[i] & (1 << (i - 1)))
        return nums

    nums = [0] + lst
    nums, index = compute(0, nums)
    nums = xor_by_remnant(nums)
    for i in range(1, len(nums)):
        nums[i], index = find_or_update(nums, i)
    return compute(0, nums), index

