from collections import defaultdict

def min_bursts(pairs):
    n = len(pairs)
    student_pairs = defaultdict(list)
    count = [0] * n

    for i, (x, y) in enumerate(pairs):
        student_pairs[i + 1].append((x, y))
        student_pairs[i + 1].append((y, x))

    for allowed, pairs in student_pairs.items():
        count[allowed] = any(all(a > b <= allowed or a <= b <= allowed for a, b in p) for p in pairs)

    return min(count)

