import sys

def count_connected_components(n, m, elements):
    # Initialize the graph with edges between elements
    graph = {i: [] for i in range(2**n)}
    for i in elements:
        for j in range(2**n):
            if i & j == 0:
                graph[i].append(j)

    # Initialize visited array with False values
    visited = [False] * (2**n)

    component_count = 0
    components = []

    def dfs(i):
        visited[i] = True
        for j in graph[i]:
            if not visited[j]:
                dfs(j)

    for i in range(2**n):
        if not visited[i]:
            component_count += 1
            components.append(component_count)
            dfs(i)

    return len(set(components))

