def d_sort_string(s, k, d):
    # Convert string to list for easy modification
    chars = list(s)
    for i in range(d):
        group = []
        for j in range(1, len(chars), d):
            group.append(chars[j % d])
        min_index = None
        for j in range(i, len(chars), d):
            if min_index is None or chars[j % d] < chars[min_index]:
