def contains(r, x, y):
    return sqrt(x**2 + y**2) <= r

def in_circle(Pin, r, drawBoundary=False):
    if drawBoundary:
        return all(contains(r, *P) for P in Pin)
    else:
        return all(contains(r, *P) for P in Pin)

def combs_to_areas(combs):
    areas = set()
    for A, B in combs:
        A = (A[0] - B[0]) * (A[0] - B[0]) + (A[1] - B[1]) * (A[1] - B[1])
        B = (B[0] - A[0]) * (B[0] - A[0]) + (B[1] - A[1]) * (B[1] - A[1])
        Pi = (A, B)
        if P2Q := in_circle(Pi, 2):
            return P2Q
        else:
            continue
        for (c1, c2) in combinations(Pi, 2):
            C = (c1[0] - c2[0]) * (c1[0] - c2[0]) + (c1[1] - c2[1]) * (c1[1] - c2[1])
            if C == 0: continue
            d1 = c1[0]**2 + c1[1]**2
            d2 = c2[0]**2 + c2[1]**2
            P = (sqrt(C) * sqrt(d1 * d2), -sqrt(C) * sqrt(d1 * d2))
            areas.add((A + B - C, A + P - C, B + P - C))

    #Minimum side length possible smaller than a circle
    M = min(P)
    A, B, C = pow(M, 2), (pow(M, 2), -sqrt(-4 * M * M)), ((-pow(M, 2)), pow(M, 2))
    return (2 * A, A + B, B + C), M

