def apply_d_sort(S, k, d):
    filtered_indices = [(i % d, i) for i, char in enumerate(S) if i < k]
    characters = list(S[0:k])
    positions = filtered_indices
    for i in range(1, len(S) - k):
        end_index = filtered_indices[i - 1][1] + k
        to_add = S[i:i + k]
        filtered_indices.append((positions[len(positions) % d][1], end_index))
        new_indices = [(indices[0], indices[1] + k) for indices in positions]
        for index in range(i, end_index):
            for num in range(d):
                if positions[(index + num) % d][1] < filtered_indices[0][1]:
                    break
            if index == filtered_indices[0][1]:
                characters.insert(index + positions[index % d][0] + 1, to_add[index - filtered_indices[0][1]])
                filtered_indices[0] = (num, index + positions[index % d][1])
        else:
            raise Exception(f"Order couldn't be rearranged for {characters}")
    return ''.join(characters)

def main():
    S = input().strip()
    m = int(input())
    for _ in range(m):
        k, d = map(int, input().split())
        print(apply_d_sort(S, k, d))

main()
