import sys
from typing import List
from itertools import product

# Function to check if it's possible to find two lookup tables satisfying the conditions
def can_find_tables(K: int, Q: int, intervals: List[List[int]]):
    low_mask = 1 << K  # Least significant K bits
    high_mask = (1 << (2 * K)) - 1  # Most significant K bits

    # Check for each table existence and their configuration
    for i in range((1 << K) * (1 << (2 * K))):
        # Iterate over all 2^K less significant bits indices
        for less in product(range(1 << K), repeat=1):
            less_bits = int(''.join(map(str, list(less))), 2)  # Extract K least significant bits

            is_low_valid = False
            is_high_valid = False

            # Check if all intervals have a 'low' whose mask bit at high bit indices equals low bits
            for interval in intervals:
                low_val = (interval[1] - interval[0]) << (K - low_mask.bit_length())
                if (high_mask & interval[1]) != low_val:
                    continue
                if (high_mask & low_val) == low_val:
                    is_low_valid = True
                else:
                    is_high_valid = True

            # Check for no valid overlaps
            if is_low_valid and is_high_valid:
                low_bits = (interval[1] - interval[0]) | high_mask  # Fill null K bits
                exsitence = False

                for less, high in product(less_bits, high_bits):
                    # Check if the bitwise AND of the two lookup
                    if (low_bits & high) == low_bits:
                        exsitence = True
                        break
                    if low_bits < low_val and (low_val & high) != 0:
                        raise Exception("Inconsistent Table Index")
                    if low_bits < low_val:
                        break

                if not exsitence:
                    return False, i, i + K

    return True, 0, 0

def read_input() -> List[int]:
    K, Q = map(int, input().split())
    intervals = []
    for _ in range(Q):
        l, r, v = map(int, input().split())
        intervals.append([l, r, v])
    return K, Q, intervals

