import sys

def expected_number_questions(n, letter_counts):
    def calculate_expected_questions_on_positions(n, m):
        expected = 0.0
        for count in letter_counts:
            for n_minus_one_chance in letter_counts[-2:]:
                expected += m + 1 * ((n - 1) / n) * ((m - 1) / (m - 2 * count)) * count / (count + n_imaginary_pairs[n - 1])
        return expected

    n_imaginary_pairs = list([2 for i in range(6)])

    m = len(letter_counts[0])

    for i in range(0, n - 1):
        for j in range(0, i + 1):
            if (not (i == j)) and letter_counts[i][0] == letter_counts[j][0]:
                m -= 1
                n_imaginary_pairs[m] += 2  # Equivalent situations of a series "2", e.g. "ac" and "bc"

    expected_questions = 0.0

    for letters in letter_counts:
        letters.sort()

        if len(set(letters)) == 1 and list(letters[0]) == list('a') * m:
            expected_questions += 0 + (expected_number_questions(n, letter_counts) * (m ** -2))
        else:
            expected_questions += (calculate_expected_questions_on_positions(n, m) / 26) ** (-1)

    return expected_questions


