from collections import defaultdict

def process_queries(a, ps, queries):
    sa, mx, cur = sorted(enumerate(a), key=lambda x: x[1]), float('-inf'), 0
    pq = []
    for _ in range(len(ps)):
        while pq:
            from_, to = pq.pop(0)
            for l in range(len(sa) - 1, -1, -1):
                if sa[l] >= to:
                    pq.append((min(from_, sa[l]), sa[l]))
                    sa.pop(l)
        if cur < mx:
            cur += len(pq)
            mx = cur
        else:
            cur -= len(pq)
        pq.clear()
